import React, { useState, useEffect } from "react";
import { db } from "../../../firebaseConfig";
import { collection, query, where, getDocs, addDoc } from "firebase/firestore";
import { useParams, useNavigate } from "react-router-dom"; // Import useNavigate
import "./Exam.css"; // Assume a separate file for styles

const Exam = () => {
  const { subject } = useParams(); // Get subject from URL params
  const [questions, setQuestions] = useState([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [answers, setAnswers] = useState([]);
  const [score, setScore] = useState(0);
  const [name, setName] = useState("");
  const [className, setClassName] = useState("");
  const [loading, setLoading] = useState(true);
  const [examFinished, setExamFinished] = useState(false);
  const navigate = useNavigate(); // Use useNavigate instead of useHistory

  // Fetch exam questions based on subject
  useEffect(() => {
    const fetchQuestions = async () => {
      setLoading(true);
      try {
        const q = query(collection(db, "exams"), where("subject", "==", subject));
        const querySnapshot = await getDocs(q);

        let fetchedQuestions = [];
        querySnapshot.forEach((doc) => {
          const data = doc.data();
          if (data.questions) {
            fetchedQuestions = data.questions; // Assuming questions are stored in an array
          }
        });

        setQuestions(fetchedQuestions);
        setAnswers(new Array(fetchedQuestions.length).fill("")); // Initialize answers array
      } catch (error) {
        console.error("Error fetching questions:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchQuestions();
  }, [subject]);

  // Handle answer change for current question
  const handleAnswerChange = (e) => {
    const updatedAnswers = [...answers];
    updatedAnswers[currentQuestionIndex] = e.target.value;
    setAnswers(updatedAnswers);
  };

  // Move to the next question
  const nextQuestion = () => {
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    } else {
      // If it's the last question, finish the exam
      setExamFinished(true);
      calculateScore();
    }
  };

  // Calculate the score based on correct answers
  const calculateScore = () => {
    let calculatedScore = 0;
    questions.forEach((q, index) => {
      if (answers[index] === q.correctAnswer) {
        calculatedScore++;
      }
    });
    setScore(calculatedScore);
  };

  // Submit the exam result to Firestore
  const handleSubmit = async () => {
    if (!name || !className) {
      alert("Please enter your name and class.");
      return;
    }

    try {
      await addDoc(collection(db, "examResults"), {
        name,
        class: className,
        subject,
        score,
        date: new Date(),
      });
      alert("Exam submitted successfully!");
      navigate("/view-scores", { state: { score, name, className, subject } }); // Use navigate instead of history.push
    } catch (error) {
      console.error("Error submitting exam:", error);
    }
  };

  return (
    <div className="exam-container">
      <h2>Exam: {subject}</h2>

      {loading ? (
        <p>Loading exam...</p>
      ) : examFinished ? (
        <div>
          <h3>Your Final Score: {score}</h3>
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Enter your name"
          />
          <input
            type="text"
            value={className}
            onChange={(e) => setClassName(e.target.value)}
            placeholder="Enter your class"
          />
          <button onClick={handleSubmit}>Submit Exam</button>
        </div>
      ) : (
        <div>
          <div className="question-container">
            <p>{currentQuestionIndex + 1}. {questions[currentQuestionIndex]?.question}</p>
            <input
              type="text"
              value={answers[currentQuestionIndex]}
              onChange={handleAnswerChange}
              placeholder="Your answer"
            />
          </div>

          <button onClick={nextQuestion}>Next Question</button>
        </div>
      )}
    </div>
  );
};

export default Exam;
